UPDATE `clickargo2`.`T_CORE_RPT_TABLE` SET `RPTT_RPT_QRY` = 'SELECT TRUCK.JOB_ID    												 AS JOB_ID,\n          JOB.JOB_SHIPMENT_TYPE                                      AS SHIPMENT_TYPE,\n          IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\') AS JOB_DT_BOOKING,\n          STATE.JBST_NAME                                            AS JOB_STATE,\n          COFF_ACCN.ACCN_NAME                                        AS CO_FF_ACCN,\n          TO_ACCN.ACCN_NAME                                          AS TO_ACCN,\n          TRIP_LOC_FROM.TLOC_LOC_NAME                                AS TLOC_LOC_NAME_FROM,\n          TRIP_LOC_TO.TLOC_LOC_NAME                                  AS TLOC_LOC_NAME_TO,\n          ( CASE\n              WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\n			  WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\n              ELSE TRUCK.JOB_DRV\n            END )                                                    AS DRV_NAME,\n          ( CASE\n              WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\n			  WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\n              ELSE TRUCK.JOB_VEH\n            END )                                                    AS VH_PLATE_NO,\n		  ( CASE\n              WHEN TRUCK.JOB_PROCESS_VIA IS NULL THEN \'WEB\' ELSE TRUCK.JOB_PROCESS_VIA\n            END )  AS PROCESS_VIA,\n            \n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\'), \'-\') AS RCD_DT_SUBMIT,\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\'), \'-\') AS RCD_DT_CANCEL,\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\'), \'-\') AS RCD_DT_ACCEPTED,\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\'), \'-\') AS RCD_DT_START,\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\'), \'-\') AS RCD_DT_COMPLETE\n   FROM   T_CK_JOB_TRUCK TRUCK\n          LEFT JOIN T_CK_JOB JOB\n                 ON TRUCK.JOB_PARENT = JOB.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP TRIP\n                 ON TRIP.TR_JOB = TRUCK.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\n                 ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\n                 ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\n          LEFT JOIN T_CORE_ACCN COFF_ACCN\n                 ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n          LEFT JOIN T_CORE_ACCN TO_ACCN\n                 ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n          LEFT JOIN T_CK_MST_JOB_STATE STATE\n                 ON JOB.JOB_STATE = STATE.JBST_ID\n          LEFT JOIN T_CK_RECORD_DATE RECORD\n                 ON RECORD.RCD_ID = JOB.JOB_DATES\n   WHERE  \n           TRUCK.JOB_PARTY_CO_FF=\'@ACCNID@\'\n          AND JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\n          AND (\n			CASE \n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'WEB\' THEN (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL)\n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'MOBILE\' THEN TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\'\n			 ELSE (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL) END\n          )\n          AND\n          (CASE WHEN JOB.JOB_STATE=\'CAN\' THEN DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_CANCEL_FROM@\'\n				WHEN JOB.JOB_STATE=\'DLV\' THEN DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_COMPLETE_FROM@\'\n                WHEN JOB.JOB_STATE=\'ACP\' THEN DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_ACCEPTED_FROM@\'\n                WHEN JOB.JOB_STATE=\'ONGOING\' THEN DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_START_FROM@\'\n                ELSE DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_SUBMIT_TO@\' END\n          )\n          AND \n           (CASE WHEN JOB.JOB_STATE=\'CAN\' THEN DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_CANCEL_TO@\'\n				WHEN JOB.JOB_STATE=\'DLV\' THEN DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_COMPLETE_TO@\'\n                WHEN JOB.JOB_STATE=\'ACP\' THEN DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_ACCEPTED_TO@\'\n                WHEN JOB.JOB_STATE=\'ONGOING\' THEN DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_START_TO@\'\n                ELSE DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_SUBMIT_TO@\' END\n          ) \n          \n        ' WHERE (`RPTT_RPTID` = 'RPT_ALL_JOBS_CO') and (`RPTT_ACCN_TYPE` = 'ACC_TYPE_CO') and (`RPTT_TBL_IDX` = '0');
UPDATE `clickargo2`.`T_CORE_RPT_TABLE` SET `RPTT_RPT_QRY` = 'SELECT TRUCK.JOB_ID    												 AS JOB_ID,\n          JOB.JOB_SHIPMENT_TYPE                                      AS SHIPMENT_TYPE,\n          IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\') AS JOB_DT_BOOKING,\n          STATE.JBST_NAME                                            AS JOB_STATE,\n          COFF_ACCN.ACCN_NAME                                        AS CO_FF_ACCN,\n          TO_ACCN.ACCN_NAME                                          AS TO_ACCN,\n          TRIP_LOC_FROM.TLOC_LOC_NAME                                AS TLOC_LOC_NAME_FROM,\n          TRIP_LOC_TO.TLOC_LOC_NAME                                  AS TLOC_LOC_NAME_TO,\n          ( CASE\n              WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\n			  WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\n              ELSE TRUCK.JOB_DRV\n            END )                                                    AS DRV_NAME,\n          ( CASE\n              WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\n			  WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\n              ELSE TRUCK.JOB_VEH\n            END )                                                    AS VH_PLATE_NO,\n		  ( CASE\n              WHEN TRUCK.JOB_PROCESS_VIA IS NULL THEN \'WEB\' ELSE TRUCK.JOB_PROCESS_VIA\n            END )  AS PROCESS_VIA,\n            \n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\'), \'-\') AS RCD_DT_SUBMIT,\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\'), \'-\') AS RCD_DT_CANCEL,\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\'), \'-\') AS RCD_DT_ACCEPTED,\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\'), \'-\') AS RCD_DT_START,\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\'), \'-\') AS RCD_DT_COMPLETE\n   FROM   T_CK_JOB_TRUCK TRUCK\n          LEFT JOIN T_CK_JOB JOB\n                 ON TRUCK.JOB_PARENT = JOB.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP TRIP\n                 ON TRIP.TR_JOB = TRUCK.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\n                 ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\n                 ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\n          LEFT JOIN T_CORE_ACCN COFF_ACCN\n                 ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n          LEFT JOIN T_CORE_ACCN TO_ACCN\n                 ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n          LEFT JOIN T_CK_MST_JOB_STATE STATE\n                 ON JOB.JOB_STATE = STATE.JBST_ID\n          LEFT JOIN T_CK_RECORD_DATE RECORD\n                 ON RECORD.RCD_ID = JOB.JOB_DATES\n   WHERE  \n           TRUCK.JOB_PARTY_TO=\'@ACCNID@\'\n          AND JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\n          AND (\n			CASE \n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'WEB\' THEN (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL)\n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'MOBILE\' THEN TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\'\n			 ELSE (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL) END\n          )\n		  AND\n           (CASE WHEN JOB.JOB_STATE=\'CAN\' THEN DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_CANCEL_FROM@\'\n				WHEN JOB.JOB_STATE=\'DLV\' THEN DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_COMPLETE_FROM@\'\n                WHEN JOB.JOB_STATE=\'ACP\' THEN DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_ACCEPTED_FROM@\'\n                WHEN JOB.JOB_STATE=\'ONGOING\' THEN DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_START_FROM@\'\n                ELSE DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_SUBMIT_TO@\' END\n          )\n          AND \n           (CASE WHEN JOB.JOB_STATE=\'CAN\' THEN DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_CANCEL_TO@\'\n				WHEN JOB.JOB_STATE=\'DLV\' THEN DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_COMPLETE_TO@\'\n                WHEN JOB.JOB_STATE=\'ACP\' THEN DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_ACCEPTED_TO@\'\n                WHEN JOB.JOB_STATE=\'ONGOING\' THEN DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_START_TO@\'\n                ELSE DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_SUBMIT_TO@\' END\n          )\n          \n        ' WHERE (`RPTT_RPTID` = 'RPT_ALL_JOBS_TO') and (`RPTT_ACCN_TYPE` = 'ACC_TYPE_TO') and (`RPTT_TBL_IDX` = '0');
UPDATE `clickargo2`.`T_CORE_RPT_TABLE` SET `RPTT_RPT_QRY` = 'SELECT TRUCK.JOB_ID    												 AS JOB_ID,\n          JOB.JOB_SHIPMENT_TYPE                                      AS SHIPMENT_TYPE,\n          IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\') AS JOB_DT_BOOKING,\n          STATE.JBST_NAME                                            AS JOB_STATE,\n          COFF_ACCN.ACCN_NAME                                        AS CO_FF_ACCN,\n          TO_ACCN.ACCN_NAME                                          AS TO_ACCN,\n          TRIP_LOC_FROM.TLOC_LOC_NAME                                AS TLOC_LOC_NAME_FROM,\n          TRIP_LOC_TO.TLOC_LOC_NAME                                  AS TLOC_LOC_NAME_TO,\n          ( CASE\n              WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\n			  WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\n              ELSE TRUCK.JOB_DRV\n            END )                                                    AS DRV_NAME,\n          ( CASE\n              WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\n			  WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\n              ELSE TRUCK.JOB_VEH\n            END )                                                    AS VH_PLATE_NO,\n		  ( CASE\n              WHEN TRUCK.JOB_PROCESS_VIA IS NULL THEN \'WEB\' ELSE TRUCK.JOB_PROCESS_VIA\n            END )  AS PROCESS_VIA,\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\'), \'-\') AS RCD_DT_COMPLETE,\n          TRIP_LOC_TO.TLOC_IS_DEVIATED AS IS_DEVIATED,\n          TRIP_LOC_TO.TLOC_DEVIATION_COMMENT AS DEVIATION_COMMENT,\n          TRIP_LOC_TO.TLOC_COMMENT AS DISCREPANCY_COMMENT\n   FROM   T_CK_JOB_TRUCK TRUCK\n          LEFT JOIN T_CK_JOB JOB\n                 ON TRUCK.JOB_PARENT = JOB.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP TRIP\n                 ON TRIP.TR_JOB = TRUCK.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\n                 ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\n                 ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\n          LEFT JOIN T_CORE_ACCN COFF_ACCN\n                 ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n          LEFT JOIN T_CORE_ACCN TO_ACCN\n                 ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n          LEFT JOIN T_CK_MST_JOB_STATE STATE\n                 ON JOB.JOB_STATE = STATE.JBST_ID\n          LEFT JOIN T_CK_RECORD_DATE RECORD\n                 ON RECORD.RCD_ID = JOB.JOB_DATES\n   WHERE  \n           TRUCK.JOB_PARTY_TO=\'@ACCNID@\'\n			  AND JOB.JOB_STATE = \'DLV\'\n			  AND TRUCK.JOB_PROCESS_VIA = \'MOBILE\'\n			  AND DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_COMPLETE_FROM@\'\n			  AND DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_COMPLETE_TO@\'\n              AND (\n				CASE WHEN \'@FIL_IS_DEVIATED_CAP@\' = \'N\' THEN (TRIP_LOC_TO.TLOC_IS_DEVIATED = \'@FIL_IS_DEVIATED_CAP@\' OR TRIP_LOC_TO.TLOC_IS_DEVIATED IS NULL)\n					ELSE TRIP_LOC_TO.TLOC_IS_DEVIATED = \'@FIL_IS_DEVIATED_CAP@\'\n                END\n              )\n              AND (\n				CASE WHEN \'@FIL_HAS_DISCREPANCY_CAP@\' = \'N\' THEN TRIP_LOC_TO.TLOC_COMMENT IS NULL OR TRIP_LOC_TO.TLOC_COMMENT = \'\'\n					ELSE TRIP_LOC_TO.TLOC_COMMENT IS NOT NULL OR TRIP_LOC_TO.TLOC_COMMENT <> \'\'\n				END\n              )\n        ' WHERE (`RPTT_RPTID` = 'RPT_JOBS_DISCREPANCY_TO') and (`RPTT_ACCN_TYPE` = 'ACC_TYPE_TO') and (`RPTT_TBL_IDX` = '0');
UPDATE `clickargo2`.`T_CORE_RPT_TABLE` SET `RPTT_RPT_QRY` = 'SELECT TRUCK.JOB_ID    												 AS JOB_ID,\n          JOB.JOB_SHIPMENT_TYPE                                      AS SHIPMENT_TYPE,\n          IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\') AS JOB_DT_BOOKING,\n          STATE.JBST_NAME                                            AS JOB_STATE,\n          COFF_ACCN.ACCN_NAME                                        AS CO_FF_ACCN,\n          TO_ACCN.ACCN_NAME                                          AS TO_ACCN,\n          TRIP_LOC_FROM.TLOC_LOC_NAME                                AS TLOC_LOC_NAME_FROM,\n          TRIP_LOC_TO.TLOC_LOC_NAME                                  AS TLOC_LOC_NAME_TO,\n          ( CASE\n              WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\n			  WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\n              ELSE TRUCK.JOB_DRV\n            END )                                                    AS DRV_NAME,\n          ( CASE\n              WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\n			  WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\'\n              WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\n              ELSE TRUCK.JOB_VEH\n            END )                                                    AS VH_PLATE_NO,\n		  ( CASE\n              WHEN TRUCK.JOB_PROCESS_VIA IS NULL THEN \'WEB\' ELSE TRUCK.JOB_PROCESS_VIA\n            END )  AS PROCESS_VIA,\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\'), \'-\') AS RCD_DT_COMPLETE,\n          TRIP_LOC_TO.TLOC_IS_DEVIATED AS IS_DEVIATED,\n          TRIP_LOC_TO.TLOC_DEVIATION_COMMENT AS DEVIATION_COMMENT,\n          TRIP_LOC_TO.TLOC_COMMENT AS DISCREPANCY_COMMENT\n   FROM   T_CK_JOB_TRUCK TRUCK\n          LEFT JOIN T_CK_JOB JOB\n                 ON TRUCK.JOB_PARENT = JOB.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP TRIP\n                 ON TRIP.TR_JOB = TRUCK.JOB_ID\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\n                 ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\n                 ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\n          LEFT JOIN T_CORE_ACCN COFF_ACCN\n                 ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\n          LEFT JOIN T_CORE_ACCN TO_ACCN\n                 ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\n          LEFT JOIN T_CK_MST_JOB_STATE STATE\n                 ON JOB.JOB_STATE = STATE.JBST_ID\n          LEFT JOIN T_CK_RECORD_DATE RECORD\n                 ON RECORD.RCD_ID = JOB.JOB_DATES\n   WHERE  \n           TRUCK.JOB_PARTY_CO_FF=\'@ACCNID@\'\n			  AND JOB.JOB_STATE = \'DLV\'\n			  AND TRUCK.JOB_PROCESS_VIA = \'MOBILE\'\n			  AND DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') >= \'@FIL_RCD_DT_COMPLETE_FROM@\'\n			  AND DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') <= \'@FIL_RCD_DT_COMPLETE_TO@\'\n              AND (\n				CASE WHEN \'@FIL_IS_DEVIATED_CAP@\' = \'N\' THEN (TRIP_LOC_TO.TLOC_IS_DEVIATED = \'@FIL_IS_DEVIATED_CAP@\' OR TRIP_LOC_TO.TLOC_IS_DEVIATED IS NULL)\n					ELSE TRIP_LOC_TO.TLOC_IS_DEVIATED = \'@FIL_IS_DEVIATED_CAP@\'\n                END\n              )\n              AND (\n				CASE WHEN \'@FIL_HAS_DISCREPANCY_CAP@\' = \'N\' THEN TRIP_LOC_TO.TLOC_COMMENT IS NULL OR TRIP_LOC_TO.TLOC_COMMENT = \'\'\n					ELSE TRIP_LOC_TO.TLOC_COMMENT IS NOT NULL OR TRIP_LOC_TO.TLOC_COMMENT <> \'\'\n				END\n              )' WHERE (`RPTT_RPTID` = 'RPT_JOBS_DISCREPANCY_CO') and (`RPTT_ACCN_TYPE` = 'ACC_TYPE_CO') and (`RPTT_TBL_IDX` = '0');

UPDATE `clickargo2`.`T_CORE_RPT_TABLE` SET `RPTT_RPT_QRY` = 'SELECT TRUCK.JOB_ID    												 AS JOB_ID,\r\n          JOB.JOB_SHIPMENT_TYPE                                      AS SHIPMENT_TYPE,\r\n          TRUCK.JOB_SHIPMENT_REF                                      AS SHIPPING_REF,\r\n          IFNULL(DATE_FORMAT(TRUCK.JOB_DT_BOOKING, \'%Y-%m-%d\'), \'-\') AS JOB_DT_BOOKING,\r\n          STATE.JBST_NAME                                            AS JOB_STATE,\r\n          COFF_ACCN.ACCN_NAME                                        AS CO_FF_ACCN,\r\n          TO_ACCN.ACCN_NAME                                          AS TO_ACCN,\r\n          TRIP_LOC_FROM.TLOC_LOC_NAME                                AS TLOC_LOC_NAME_FROM,\r\n          TRIP_LOC_TO.TLOC_LOC_NAME                                  AS TLOC_LOC_NAME_TO,\r\n          ( CASE\r\n              WHEN TRUCK.JOB_DRV IS NOT NULL THEN (SELECT DRV.DRV_NAME FROM T_CK_CT_DRV DRV WHERE DRV.DRV_ID = TRUCK.JOB_DRV)\r\n			  WHEN TRUCK.JOB_DRV IS NULL AND TRUCK.JOB_DRV_OTH IS NULL THEN \'-\'\r\n              WHEN TRUCK.JOB_DRV IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_DRV_OTH, \'drvName=\', -1), \'}\', 1)\r\n              ELSE TRUCK.JOB_DRV\r\n            END )                                                    AS DRV_NAME,\r\n          ( CASE\r\n              WHEN TRUCK.JOB_VEH IS NOT NULL THEN (SELECT VEH.VH_PLATE_NO FROM T_CK_CT_VEH VEH WHERE  VEH.VH_ID = TRUCK.JOB_VEH)\r\n			  WHEN TRUCK.JOB_VEH IS NULL AND TRUCK.JOB_VEH_OTH IS NULL THEN \'-\'\r\n              WHEN TRUCK.JOB_VEH IS NULL THEN SUBSTRING_INDEX(SUBSTRING_INDEX(TRUCK.JOB_VEH_OTH, \'vhPlateNo=\', -1), \',\', 1)\r\n              ELSE TRUCK.JOB_VEH\r\n            END )                                                    AS VH_PLATE_NO,\r\n		  ( CASE\r\n              WHEN TRUCK.JOB_PROCESS_VIA IS NULL THEN \'WEB\' ELSE TRUCK.JOB_PROCESS_VIA\r\n            END )  AS PROCESS_VIA,\r\n            \r\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\'), \'-\') AS RCD_DT_SUBMIT,\r\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\'), \'-\') AS RCD_DT_CANCEL,\r\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\'), \'-\') AS RCD_DT_ACCEPTED,\r\n		  IFNULL(DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\'), \'-\') AS RCD_DT_START,\r\n          IFNULL(DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\'), \'-\') AS RCD_DT_COMPLETE\r\n   FROM   T_CK_JOB_TRUCK TRUCK\r\n          LEFT JOIN T_CK_JOB JOB\r\n                 ON TRUCK.JOB_PARENT = JOB.JOB_ID\r\n          LEFT JOIN T_CK_CT_TRIP TRIP\r\n                 ON TRIP.TR_JOB = TRUCK.JOB_ID\r\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_FROM\r\n                 ON TRIP_LOC_FROM.TLOC_ID = TRIP.TR_FROM\r\n          LEFT JOIN T_CK_CT_TRIP_LOCATION TRIP_LOC_TO\r\n                 ON TRIP_LOC_TO.TLOC_ID = TRIP.TR_TO\r\n          LEFT JOIN T_CORE_ACCN COFF_ACCN\r\n                 ON COFF_ACCN.ACCN_ID = TRUCK.JOB_PARTY_CO_FF\r\n          LEFT JOIN T_CORE_ACCN TO_ACCN\r\n                 ON TO_ACCN.ACCN_ID = TRUCK.JOB_PARTY_TO\r\n          LEFT JOIN T_CK_MST_JOB_STATE STATE\r\n                 ON JOB.JOB_STATE = STATE.JBST_ID\r\n          LEFT JOIN T_CK_RECORD_DATE RECORD\r\n                 ON RECORD.RCD_ID = JOB.JOB_DATES\r\n WHERE  \r\n    TRUCK.JOB_PARTY_TO = \'@ACCNID@\'\r\n    AND (\r\n        \'@FIL_JOB_STATE_CAP@\' = \'ALL\' \r\n        OR (JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\r\n					OR (\r\n						JOB.JOB_STATE = \'@FIL_JOB_STATE_CAP@\'\r\n						AND (\r\n							CASE \r\n									WHEN JOB.JOB_STATE = \'CAN\' THEN DATE_FORMAT(RECORD.RCD_DT_CANCEL, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_CANCEL_FROM@\' AND \'@FIL_RCD_DT_CANCEL_TO@\'\r\n									WHEN JOB.JOB_STATE = \'DLV\' THEN DATE_FORMAT(RECORD.RCD_DT_COMPLETE, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_COMPLETE_FROM@\' AND \'@FIL_RCD_DT_COMPLETE_TO@\'\r\n									WHEN JOB.JOB_STATE = \'ACP\' THEN DATE_FORMAT(RECORD.RCD_DT_ACCEPTED, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_ACCEPTED_FROM@\' AND \'@FIL_RCD_DT_ACCEPTED_TO@\'\r\n									WHEN JOB.JOB_STATE = \'ONGOING\' THEN DATE_FORMAT(RECORD.RCD_DT_START, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_START_FROM@\' AND \'@FIL_RCD_DT_START_TO@\'\r\n									ELSE DATE_FORMAT(RECORD.RCD_DT_SUBMIT, \'%Y-%m-%d\') BETWEEN \'@FIL_RCD_DT_SUBMIT_FROM@\' AND \'@FIL_RCD_DT_SUBMIT_TO@\'\r\n							END\r\n					)\r\n				)\r\n			)\r\n    )\r\n		AND (\r\n			CASE \r\n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'WEB\' THEN (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL)\r\n             WHEN \'@FIL_JOB_PROCESS_VIA_CAP@\' = \'MOBILE\' THEN TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\'\r\n			 ELSE (TRUCK.JOB_PROCESS_VIA = \'@FIL_JOB_PROCESS_VIA_CAP@\' OR TRUCK.JOB_PROCESS_VIA IS NULL) END\r\n          )' WHERE `RPTT_RPTID` = 'RPT_ALL_JOBS_TO' AND `RPTT_ACCN_TYPE` = 'ACC_TYPE_TO' AND `RPTT_TBL_IDX` = 0;

